/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'fs'

// Validate arguments
if (process.argv.length !== 3) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  process.stderr.write('error: failed to read stdin\n')
  process.exit(2)
}

// Parse the document
try {
  const document = parseDocument(input)

  if (mode === 'json') {
    outputJson(document)
  } else {
    outputKeys(document)
  }
} catch (error) {
  process.stderr.write(error.message + '\n')
  process.exit(2)
}

/**
 * Parse the TOML document
 */
function parseDocument(input) {
  // Split into lines and drop empty tail
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parser = new Parser(lines)
  return parser.parse()
}

class Parser {
  constructor(lines) {
    this.lines = lines
    this.root = {}
    this.current = this.root
    this.currentPath = []
    this.lineNum = 0
    this.definedKeys = new Set()
    this.definedTables = new Set()
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Strip comments and handle quoted strings
    const trimmedLine = this.stripComments(line)

    if (this.isBlank(trimmedLine)) {
      return
    }

    if (trimmedLine[0] === '[') {
      this.parseHeader(trimmedLine)
    } else {
      this.parseKeyValue(trimmedLine)
    }
  }

  stripComments(line) {
    let inBasicString = false
    let inLiteralString = false
    let escaped = false
    let result = ''

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (escaped) {
        result += char
        escaped = false
        continue
      }

      if (char === '\\' && inBasicString) {
        result += char
        escaped = true
        continue
      }

      if (char === '"' && !inLiteralString) {
        inBasicString = !inBasicString
        result += char
        continue
      }

      if (char === "'" && !inBasicString) {
        inLiteralString = !inLiteralString
        result += char
        continue
      }

      if ((char === '#' || char === ';') && !inBasicString && !inLiteralString) {
        break
      }

      result += char
    }

    return result
  }

  isBlank(line) {
    // Check if line is only whitespace
    return /^\s*$/.test(line)
  }

  parseHeader(line) {
    let i = 0

    // Skip leading whitespace
    while (i < line.length && /[\s]/.test(line[i])) i++

    if (line[i] !== '[') {
      throw this.error('expected [ at start of header')
    }
    i++

    // Check for array of tables
    let isArray = false
    if (line[i] === '[') {
      isArray = true
      i++
    }

    // Skip whitespace
    while (i < line.length && /[\s]/.test(line[i])) i++

    // Parse the name
    const names = []
    while (i < line.length) {
      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === ']') break

      // Parse a name
      let name
      if (line[i] === '"') {
        // Basic string
        i++
        let str = ''
        let escaped = false
        while (i < line.length) {
          if (escaped) {
            str += line[i]
            escaped = false
          } else if (line[i] === '\\') {
            escaped = true
          } else if (line[i] === '"') {
            break
          } else {
            str += line[i]
          }
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        name = this.decodeBasicString(str)
        i++
      } else if (line[i] === "'") {
        // Literal string
        i++
        let str = ''
        while (i < line.length && line[i] !== "'") {
          str += line[i]
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        name = str
        i++
      } else {
        // Bare word
        let word = ''
        while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) {
          word += line[i]
          i++
        }
        if (word === '') {
          throw this.error('expected a name')
        }
        name = word
      }

      names.push(name)

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === '.') {
        i++
      } else if (line[i] === ']') {
        break
      }
    }

    if (i >= line.length) {
      throw this.error('unterminated table header')
    }

    i++ // Skip ]
    if (isArray) {
      if (i >= line.length || line[i] !== ']') {
        throw this.error('unterminated table header')
      }
      i++
    }

    // Skip whitespace after closing bracket
    while (i < line.length && /[\s]/.test(line[i])) i++

    // Check for trailing text
    if (i < line.length) {
      throw this.error('trailing text after a table header')
    }

    // Now apply the header
    this.applyHeader(names, isArray)
  }

  applyHeader(names, isArray) {
    const path = names.join('.')

    if (isArray) {
      // Array of tables
      let obj = this.root
      const fullPath = []

      for (let i = 0; i < names.length - 1; i++) {
        fullPath.push(names[i])
        const key = names[i]
        if (!(key in obj)) {
          obj[key] = {}
        } else if (typeof obj[key] !== 'object' || Array.isArray(obj[key])) {
          throw this.error(`${fullPath.join('.')} is not a table`)
        }
        obj = obj[key]
      }

      fullPath.push(names[names.length - 1])
      const lastName = names[names.length - 1]

      if (!(lastName in obj)) {
        obj[lastName] = []
      } else if (!Array.isArray(obj[lastName])) {
        throw this.error(`${fullPath.join('.')} is not an array of tables`)
      }

      const newTable = {}
      obj[lastName].push(newTable)
      this.current = newTable
      this.currentPath = fullPath
    } else {
      // Regular table
      const pathStr = names.join('.')

      if (this.definedTables.has(pathStr)) {
        throw this.error(`table ${pathStr} is defined twice`)
      }
      this.definedTables.add(pathStr)

      let obj = this.root
      const fullPath = []

      for (let i = 0; i < names.length; i++) {
        fullPath.push(names[i])
        const key = names[i]

        if (!(key in obj)) {
          obj[key] = {}
        } else if (typeof obj[key] !== 'object' || Array.isArray(obj[key])) {
          throw this.error(`${fullPath.join('.')} is not a table`)
        }

        obj = obj[key]
      }

      this.current = obj
      this.currentPath = fullPath
    }
  }

  parseKeyValue(line) {
    let i = 0

    // Skip leading whitespace
    while (i < line.length && /[\s]/.test(line[i])) i++

    // Parse the key (dotted name)
    const keys = []

    while (i < line.length) {
      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === '=') break

      // Parse a name
      let key
      if (line[i] === '"') {
        // Basic string
        i++
        let str = ''
        let escaped = false
        while (i < line.length) {
          if (escaped) {
            str += line[i]
            escaped = false
          } else if (line[i] === '\\') {
            escaped = true
          } else if (line[i] === '"') {
            break
          } else {
            str += line[i]
          }
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        key = this.decodeBasicString(str)
        i++
      } else if (line[i] === "'") {
        // Literal string
        i++
        let str = ''
        while (i < line.length && line[i] !== "'") {
          str += line[i]
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        key = str
        i++
      } else {
        // Bare word
        let word = ''
        while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) {
          word += line[i]
          i++
        }
        if (word === '') {
          throw this.error('expected a name')
        }
        key = word
      }

      keys.push(key)

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === '=') break
      if (line[i] === '.') {
        i++
      } else {
        throw this.error('expected key = value')
      }
    }

    if (i >= line.length || line[i] !== '=') {
      throw this.error('expected key = value')
    }
    i++

    // Skip whitespace
    while (i < line.length && /[\s]/.test(line[i])) i++

    // Parse the value
    const valueResult = this.parseValue(line, i)
    const value = valueResult.value
    let newI = valueResult.i

    // Skip whitespace after value
    while (newI < line.length && /[\s]/.test(line[newI])) newI++

    // Check for trailing text
    if (newI < line.length) {
      throw this.error('trailing text after a value')
    }

    // Set the value in the current table
    let obj = this.current
    for (let j = 0; j < keys.length - 1; j++) {
      const key = keys[j]
      if (!(key in obj)) {
        obj[key] = {}
      } else if (typeof obj[key] !== 'object' || Array.isArray(obj[key])) {
        const pathParts = [...this.currentPath, ...keys.slice(0, j + 1)]
        throw this.error(`${pathParts.join('.')} is not a table`)
      }
      obj = obj[key]
    }

    const lastKey = keys[keys.length - 1]
    const fullPath = [...this.currentPath, ...keys].join('.')

    if (lastKey in obj) {
      throw this.error(`key ${fullPath} is defined twice`)
    }

    obj[lastKey] = value
  }

  parseValue(line, startI) {
    let i = startI

    if (i >= line.length) {
      throw this.error('expected a value')
    }

    // Try to parse each value type
    if (line[i] === 't' && line.substr(i, 4) === 'true') {
      return { value: true, i: i + 4 }
    }

    if (line[i] === 'f' && line.substr(i, 5) === 'false') {
      return { value: false, i: i + 5 }
    }

    if (line[i] === '"') {
      return this.parseBasicString(line, i)
    }

    if (line[i] === "'") {
      return this.parseLiteralString(line, i)
    }

    if (line[i] === '[') {
      return this.parseArray(line, i)
    }

    if (line[i] === '{') {
      return this.parseInlineTable(line, i)
    }

    // Try number or bare word
    let start = i

    // Optional sign
    if (line[i] === '+' || line[i] === '-') {
      i++
    }

    // Parse digits and underscores
    let hasDigits = false
    let hasDecimal = false
    let hasExponent = false

    while (i < line.length) {
      if (/[0-9]/.test(line[i])) {
        hasDigits = true
        i++
      } else if (line[i] === '_' && hasDigits && i + 1 < line.length && /[0-9]/.test(line[i + 1])) {
        i++
      } else if (line[i] === '.' && !hasDecimal && !hasExponent) {
        hasDecimal = true
        i++
        if (i >= line.length || !/[0-9]/.test(line[i])) {
          throw this.error(`invalid value ${line.substr(start, i - start)}`)
        }
      } else if ((line[i] === 'e' || line[i] === 'E') && !hasExponent) {
        hasExponent = true
        i++
        if (i < line.length && (line[i] === '+' || line[i] === '-')) {
          i++
        }
        if (i >= line.length || !/[0-9]/.test(line[i])) {
          throw this.error(`invalid value ${line.substr(start, i - start)}`)
        }
      } else {
        break
      }
    }

    if (hasDigits) {
      const numStr = line.substr(start, i - start).replace(/_/g, '')
      if (hasDecimal || hasExponent) {
        return { value: parseFloat(numStr), i }
      } else {
        return { value: parseInt(numStr, 10), i }
      }
    }

    // Bare word that's not a valid value
    let word = ''
    while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) {
      word += line[i]
      i++
    }

    if (word) {
      throw this.error(`invalid value ${word}`)
    }

    throw this.error('expected a value')
  }

  parseBasicString(line, startI) {
    let i = startI + 1
    let str = ''
    let escaped = false

    while (i < line.length) {
      if (escaped) {
        const char = line[i]
        switch (char) {
          case 'n':
            str += '\n'
            break
          case 't':
            str += '\t'
            break
          case 'r':
            str += '\r'
            break
          case '\\':
            str += '\\'
            break
          case '"':
            str += '"'
            break
          case '0':
            str += '\0'
            break
          case 'u':
            // Parse \uXXXX
            i++
            if (i + 3 >= line.length) {
              throw this.error('invalid escape \\u')
            }
            const hex = line.substr(i, 4)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw this.error('invalid escape \\u')
            }
            str += String.fromCharCode(parseInt(hex, 16))
            i += 3
            break
          default:
            throw this.error(`invalid escape \\${char}`)
        }
        escaped = false
      } else if (line[i] === '\\') {
        escaped = true
      } else if (line[i] === '"') {
        return { value: str, i: i + 1 }
      } else {
        str += line[i]
      }
      i++
    }

    throw this.error('unterminated string')
  }

  parseLiteralString(line, startI) {
    let i = startI + 1
    let str = ''

    while (i < line.length && line[i] !== "'") {
      str += line[i]
      i++
    }

    if (i >= line.length) {
      throw this.error('unterminated string')
    }

    return { value: str, i: i + 1 }
  }

  parseArray(line, startI) {
    let i = startI + 1
    const values = []

    while (i < line.length) {
      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === ']') {
        return { value: values, i: i + 1 }
      }

      if (values.length > 0) {
        // Expect comma
        if (line[i] !== ',') {
          throw this.error('expected , in array')
        }
        i++

        // Skip whitespace
        while (i < line.length && /[\s]/.test(line[i])) i++

