  parseBasicString(line, startI) {
    let i = startI + 1
    let str = ''
    let escaped = false

    while (i < line.length) {
      if (escaped) {
        const char = line[i]
        switch (char) {
          case 'n':
            str += '\n'
            break
          case 't':
            str += '\t'
            break
          case 'r':
            str += '\r'
            break
          case '\\':
            str += '\\'
            break
          case '"':
            str += '"'
            break
          case '0':
            str += '\0'
            break
          case 'u':
