  stripComments(line) {
    let inBasicString = false
    let inLiteralString = false
    let escaped = false
    let result = ''

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (escaped) {
        result += char
        escaped = false
        continue
      }

      if (char === '\\' && inBasicString) {
        result += char
        escaped = true
        continue
      }

      if (char === '"' && !inLiteralString) {
        inBasicString = !inBasicString
        result += char
        continue
      }

      if (char === "'" && !inBasicString) {
        inLiteralString = !inLiteralString
        result += char
        continue
      }

      if ((char === '#' || char === ';') && !inBasicString && !inLiteralString) {
        break
      }

      result += char
